INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (118, 'hotGestoresComCrs', 'Gestores ativos com CRs concatenados.', 'SQL', 'SELECT g.*, GROUP_CONCAT(gc.CR_ID) as CR_IDS FROM GESTOR g
